import { lazy } from 'react';
import { CalendarClock as IcCalendarClock, HelpCircle as IcHelpCircle, MessageSquare as IcMessageSquare } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Interviews — hub page for the Recruitment menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 3 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'InterviewCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const InterviewScheduler = lazy(() => import('./InterviewScheduler'));
const InterviewFeedback = lazy(() => import('./InterviewFeedback'));
const InterviewQuestionBank = lazy(() => import('./InterviewQuestionBank'));

export const TABS = [
  { id: 'schedule', label: 'Schedule', icon: IcCalendarClock, page: 'InterviewScheduler', Component: InterviewScheduler },
  { id: 'feedback', label: 'Feedback', icon: IcMessageSquare, page: 'InterviewFeedback', Component: InterviewFeedback },
  { id: 'questions', label: 'Question Bank', icon: IcHelpCircle, page: 'InterviewQuestionBank', Component: InterviewQuestionBank },
];

export default function InterviewCenter({ setPage }) {
  return (
    <TabHub
      icon={IcCalendarClock}
      eyebrow="Recruitment"
      title="Interviews"
      subtitle="Scheduling, panel feedback and the question bank"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
